<script module lang="ts">
/**
 * Menu's command list on right-click or long-press, at the press point (`design/components/context-menu.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/context-menu.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext, type Snippet } from 'svelte'

import * as zag from '@zag-js/menu'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  agentMember,
  attributes,
  chooseMenuEntry,
  followHighlight,
  joinSlot,
  menuChoices,
  mergeParts,
  normalizeProps,
  useDirection,
  useMediaQuery,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/context-menu.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import ContextMenuSubmenu from './ContextMenuSubmenu.svelte'
import Kbd from '../structure/Kbd.svelte'
import type { MenuEntry } from './Menu.svelte'

export interface ContextMenuProps {
  /**
   * The surface: one element, which may be non-interactive, because the trigger is the area, not
   * a control. The member merges into the child instead of wrapping it in a box. A wrapper
   * element around a `Table.Row` would break the table, and the panel anchors to the press
   * point, so the trigger span's rect is never needed.
   */
  children: Snippet
  /**
   * Entries in Menu's grammar (`menu.md`), including submenus; this member does not redefine it.
   */
  entries: MenuEntry[]
  /**
   * Notifies apps that pause row hover states or refresh entries on open.
   */
  onOpenChange?: (open: boolean) => void
  /**
   * Menu's `presentation`, passed through (`menu.md`; the sheet presentation): `'auto'` uses a
   * sheet below `30rem`, and `'popover'` keeps the press-point popper at every width. Like
   * Menu's, the union is closed and has no always-`'sheet'` value.
   */
  presentation?: 'auto' | 'popover'
}
</script>

<script lang="ts">
let { children, entries, onOpenChange, presentation = 'auto' }: ContextMenuProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
let restoreTo = $state(null as HTMLElement | null)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
let surface = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const sheeting = $derived(presentation === 'auto' && phone.current)
const flat = $derived(
  entries.flatMap((entry) =>
    entry.kind === 'submenu'
      ? [{ kind: 'label' as const, label: entry.label }, ...(entry.disabled ? [] : entry.items)]
      : [entry],
  ),
)
const remember = $derived((pressed: boolean) => {
  const active = document.activeElement
  const focused = active instanceof HTMLElement && active !== document.body ? active : null
  restoreTo = pressed ? focused : (focused ?? restoreTo)
})
const documentDirection = useDirection(() => surface)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      positioning: { placement: 'right-start', gutter: 0 },
      onOpenChange: (details) => {
        onOpenChange?.(details.open)
      },
      onSelect: (details) => {
        flat.forEach(
          (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
        )
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
setContext('polymorph:ContextMenu', {
  get api() {
    return api
  },
  get service() {
    return service
  },
})
const effect1 = () => {
  followHighlight(panel, api.highlightedValue)
}
watchEffect(effect1, { watch: () => api.highlightedValue })
const effect2 = () => {
  api.open || requestAnimationFrame(() => (restoreTo?.focus(), (restoreTo = null)))
}
watchEffect(effect2, { watch: () => api.open, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'ContextMenu',
    element: () => surface,
    state: () => ({ open: api.open, entries: menuChoices(entries) }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => chooseMenuEntry(entries, value) && api.open && api.setOpen(false),
      },
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<span
    bind:this={surface}
    {...attributes(mergeParts(api.getContextTriggerProps(), { onContextmenuCapture: () => { remember(false) }, onPointerdownCapture: () => { remember(true) } }))}
    class={styles.surface}
    style:user-select={'auto'}
    style:-webkit-user-select={'auto'}
    data-member="context-menu"
    >{@render children?.()
  }</span
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          {...attributes(mergeParts(api.getContentProps(), { onFocus: () => { followHighlight(panel, api.highlightedValue) } }))}
          class={styles.content}
          style:--radix-context-menu-content-available-height={'var(--available-height)'}
          style:--radix-context-menu-content-transform-origin={'var(--transform-origin)'}
          hidden={undefined}
          data-member="context-menu"
          >{#each entries as entry, index (index)
            }{#if entry.kind === 'separator'
              }<div {...attributes(api.getSeparatorProps())} class={styles.separator}></div
            >{:else if entry.kind === 'label'
              }<div class={styles.groupLabel}>{entry.label}</div
            >{:else if entry.kind === 'checkbox'
              }<div
                {...attributes(mergeParts(api.getOptionItemProps({ type: 'checkbox', value: entry.label, checked: entry.checked, disabled: entry.disabled, closeOnSelect: false, onCheckedChange: entry.onCheckedChange }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                class={[styles.item, styles.checkbox]}
                tabindex="-1"
                ><span class={styles.check}
                  >{#if entry.checked}<Icon name="confirm" size="sm" />{/if
                }</span
                ><span class={styles.label}>{entry.label}</span
              ></div
            >{:else if entry.kind === 'submenu'
              }<ContextMenuSubmenu {entry}
            />{:else
              }<div
                {...attributes(mergeParts(api.getItemProps({ value: entry.label, disabled: entry.disabled }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                class={styles.item}
                data-tone={entry.tone ?? 'neutral'}
                tabindex="-1"
                >{#if entry.icon !== undefined
                  }<span class={styles.glyph}><Icon name={entry.icon} size="sm" /></span
                >{/if
                }<span class={styles.label}>{entry.label}</span
                >{#if entry.kbd !== undefined
                  }<span class={styles.hint}><Kbd>{entry.kbd}</Kbd></span
                >{/if
              }</div
            >{/if
          }{/each
        }</div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          class={sheet.panel}
          data-presentation="sheet"
          data-state={api.open ? 'open' : 'closed'}
          tabindex="-1"
          ><div
            bind:this={panel}
            {...attributes(mergeParts(api.getContentProps(), { onFocus: () => { followHighlight(panel, api.highlightedValue) } }))}
            class={styles.sheetList}
            hidden={undefined}
            data-member="context-menu"
            >{#each flat as entry, index (index)
              }{#if entry.kind === 'separator'
                }<div {...attributes(api.getSeparatorProps())} class={styles.separator}></div
              >{:else if entry.kind === 'label'
                }<div class={styles.groupLabel}>{entry.label}</div
              >{:else if entry.kind === 'checkbox'
                }<div
                  {...attributes(mergeParts(api.getOptionItemProps({ type: 'checkbox', value: entry.label, checked: entry.checked, disabled: entry.disabled, closeOnSelect: false, onCheckedChange: entry.onCheckedChange }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={[styles.item, styles.checkbox]}
                  tabindex="-1"
                  ><span class={styles.check}
                    >{#if entry.checked}<Icon name="confirm" size="sm" />{/if
                  }</span
                  ><span class={styles.label}>{entry.label}</span
                ></div
              >{:else
                }<div
                  {...attributes(mergeParts(api.getItemProps({ value: entry.label, disabled: entry.disabled }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={styles.item}
                  data-tone={entry.tone ?? 'neutral'}
                  tabindex="-1"
                  >{#if entry.icon !== undefined
                    }<span class={styles.glyph}><Icon name={entry.icon} size="sm" /></span
                  >{/if
                  }<span class={styles.label}>{entry.label}</span
                  >{#if entry.kbd !== undefined
                    }<span class={styles.hint}><Kbd>{entry.kbd}</Kbd></span
                  >{/if
                }</div
              >{/if
            }{/each
          }</div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
